"""Read-only helpers for exploring SQLite output generated by BHSim."""
from __future__ import annotations

import io
import sqlite3
import tempfile
import zipfile
from pathlib import Path

# Only these statements and tables are exposed to the browser interface.
TABLES = {
    "Individuals": "individuals",
    "Programs": "programs",
    "Employees": "employees",
    "Enrollments": "individual_programs",
    "Visits": "visits",
    "Visit types": "visit_types",
    "Employee programs": "employee_programs",
    "Assessments": "assessments",
    "Assessment responses": "assessment_responses_readable",
    "Assessment scores": "assessment_scores",
    "Productivity": "visit_productivity",
}


def query_db(database: bytes, sql: str, params: tuple = ()) -> tuple[list[str], list[tuple]]:
    """Open a temporary, read-only connection; never execute user-provided SQL."""
    with tempfile.TemporaryDirectory(prefix="bhsim-explore-") as temp:
        db = Path(temp) / "dataset.db"
        db.write_bytes(database)
        con = sqlite3.connect(f"file:{db.as_posix()}?mode=ro", uri=True)
        try:
            cursor = con.execute(sql, params)
            return [column[0] for column in cursor.description], cursor.fetchall()
        finally:
            con.close()


def overview(database: bytes) -> dict[str, int]:
    """Count core objects using the source generator's real schema."""
    wanted = ["individuals", "employees", "programs", "individual_programs", "visits", "assessments"]
    sql = " UNION ALL ".join(f"SELECT '{table}', COUNT(*) FROM {table}" for table in wanted)
    _, rows = query_db(database, sql)
    return dict(rows)


def preview(database: bytes, table: str, limit: int = 30) -> tuple[list[str], list[tuple]]:
    if table not in TABLES.values():
        raise ValueError("Unsupported table")
    if not 1 <= limit <= 100:
        raise ValueError("Preview limit must be between 1 and 100")
    return query_db(database, f'SELECT * FROM "{table}" LIMIT ?', (limit,))


def appointment_summary(database: bytes) -> tuple[list[str], list[tuple]]:
    return query_db(database, """SELECT visit_status, COUNT(*) AS visits FROM visits
                       GROUP BY visit_status ORDER BY visits DESC""")


def relationship_preview(database: bytes) -> tuple[list[str], list[tuple]]:
    return query_db(database, """SELECT v.visit_id, i.full_name AS individual,
        p.program_code AS program, e.full_name AS employee,
        v.visit_status, v.scheduled_start
        FROM visits v JOIN individuals i ON v.individual_id=i.individual_id
        JOIN programs p ON v.program_id=p.program_id
        JOIN employees e ON v.employee_id=e.employee_id
        ORDER BY v.scheduled_start DESC LIMIT 30""")


def zip_csv_export(folder: Path) -> bytes:
    stream = io.BytesIO()
    with zipfile.ZipFile(stream, "w", zipfile.ZIP_DEFLATED) as archive:
        for file in sorted(folder.glob("*.csv")):
            archive.write(file, arcname=file.name)
    return stream.getvalue()

# Lightweight field guide for the playground, not an official versioned dictionary.
FIELD_DESCRIPTIONS = {
    "individual_id": "Unique identifier for a fictional individual; stored as text.",
    "employee_id": "Unique identifier for a fictional staff member; stored as text.",
    "program_id": "Identifier linking a record to a behavioral health program.",
    "visit_id": "Unique identifier for a generated appointment.",
    "assessment_id": "Identifier linking an assessment to its responses and scores.",
    "full_name": "Fictional display name; names are not guaranteed to be unique.",
    "date_of_birth": "Synthetic date of birth.",
    "sex": "Synthetic sex-designation code. M = Male; F = Female; X = other/unspecified designation. Not a gender-identity field.",
    "visit_status": "Generated appointment status, such as completed, no-show, or canceled.",
    "scheduled_start": "Scheduled appointment start date and time.",
    "actual_start": "Actual service start time, when a service took place.",
    "actual_end": "Actual service end time, when a service took place.",
    "total_score": "Calculated total for a complete simulated assessment.",
    "score_value": "Numeric score associated with a selected answer.",
    "program_code": "Short identifier representing a generated program.",
}


def data_dictionary(database: bytes, table: str) -> list[dict]:
    """Read actual table metadata; annotations are deliberately partial."""
    if table not in TABLES.values():
        raise ValueError("Unsupported table")
    _, fields = query_db(database, f'PRAGMA table_info("{table}")')
    _, links = query_db(database, f'PRAGMA foreign_key_list("{table}")')
    fk_by_column = {entry[3]: f"{entry[2]}.{entry[4]}" for entry in links}
    result = []
    for _, name, kind, not_null, _, primary_key in fields:
        result.append({
            "Column": name,
            "SQLite type": kind or "(unspecified)",
            "Primary key": bool(primary_key),
            "Required": bool(not_null or primary_key),
            "References": fk_by_column.get(name, ""),
            "Description": FIELD_DESCRIPTIONS.get(name, "Not yet documented; inspect source schema."),
        })
    return result
